use crate::generator::Random;
use crate::shrink::Shrinker;
use crate::{Case, Error, Generator, Work, text};
use serde::{Deserialize, Serialize};

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum TestStatus {
    Passed,
    Failed,
    Exhausted,
    Inconclusive,
    Error,
    NotFailing,
}
#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Phase {
    Generation,
    Baseline,
    Shrink,
    Confirmation,
    Replay,
}
#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum ShrinkStatus {
    Minimal,
    Bounded,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "status", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Verdict {
    Matched {},
    Mismatch { signature: String },
    Invalid {},
    Unknown { reason: String },
    Error { message: String },
}
impl Verdict {
    fn validate(&self) -> Result<(), Error> {
        match self {
            Self::Mismatch { signature } => text(signature),
            Self::Unknown { reason } => text(reason),
            Self::Error { message } => text(message),
            _ => Ok(()),
        }
    }
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct Plan {
    pub generator: Generator,
    pub seed: u32,
    pub cases: u32,
    pub max_attempts: u32,
    pub max_shrink_checks: u32,
    pub max_work: u32,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Trial {
    pub id: u32,
    pub phase: Phase,
    pub case: Case,
    pub verdict: Verdict,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ShrinkSummary {
    pub status: ShrinkStatus,
    pub checks: u32,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct TestResult {
    pub status: TestStatus,
    pub reason: Option<String>,
    pub seed: u32,
    pub attempts: u32,
    pub cases: u32,
    pub skips: u32,
    pub work: u32,
    pub shrink: Option<ShrinkSummary>,
    pub counterexample: Option<Case>,
    pub signature: Option<String>,
    pub trials: Vec<Trial>,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Effect {
    Evaluate { id: u32, phase: Phase, case: Case },
    Done { result: TestResult },
}
pub struct Session {
    plan: Option<Plan>,
    generator: Option<Generator>,
    random: Random,
    work: Work,
    result: TestResult,
    shrinker: Option<Shrinker>,
    effect: Effect,
    next_id: u32,
    replay_signature: Option<String>,
    record_bytes: usize,
}
impl Session {
    fn new(seed: u32, maximum: u32) -> Self {
        let result = TestResult {
            status: TestStatus::Inconclusive,
            reason: None,
            seed,
            attempts: 0,
            cases: 0,
            skips: 0,
            work: 0,
            shrink: None,
            counterexample: None,
            signature: None,
            trials: Vec::new(),
        };
        Self {
            plan: None,
            generator: None,
            random: Random(seed),
            work: Work { used: 0, maximum },
            effect: Effect::Done {
                result: result.clone(),
            },
            result,
            shrinker: None,
            next_id: 1,
            replay_signature: None,
            record_bytes: 0,
        }
    }
    pub fn property(mut plan: Plan) -> Result<Self, Error> {
        if plan.seed == 0
            || plan.cases == 0
            || plan.cases > 256
            || plan.max_attempts < plan.cases
            || plan.max_attempts > 4096
            || !(2..=512).contains(&plan.max_shrink_checks)
        {
            return Err(Error::protocol("invalid property budgets or seed"));
        }
        plan.generator = plan.generator.normalize()?;
        let mut session = Self::new(plan.seed, plan.max_work);
        session.generator = Some(plan.generator.clone());
        session.plan = Some(plan);
        session.generate();
        Ok(session)
    }
    pub fn shrink(
        generator: Generator,
        case: Case,
        max_checks: u32,
        max_work: u32,
    ) -> Result<Self, Error> {
        if !(2..=512).contains(&max_checks) {
            return Err(Error::protocol("shrinking needs 2-512 checks"));
        }
        let generator = generator.normalize()?;
        let case = case.normalize()?;
        if case.generator_id != generator.id || case.generator_version != generator.version {
            return Err(Error::protocol("case generator identity differs"));
        }
        let mut session = Self::new(case.seed, max_work);
        session.generator = Some(generator);
        session.shrinker = Some(Shrinker::new(case.clone(), String::new(), max_checks));
        match session
            .generator
            .as_ref()
            .expect("generator")
            .accepts(&case.actions, &mut session.work)
        {
            Ok(true) => session.emit(Phase::Baseline, case),
            Ok(false) => return Err(Error::protocol("initial counterexample is not enabled")),
            Err(()) => session.finish(TestStatus::Inconclusive, Some("work".into())),
        }
        Ok(session)
    }
    pub fn replay(case: Case, expected_signature: Option<String>) -> Result<Self, Error> {
        let case = case.normalize()?;
        if let Some(signature) = &expected_signature {
            text(signature)?;
        }
        let mut session = Self::new(case.seed, 0);
        session.result.attempts = 1;
        session.replay_signature = expected_signature;
        session.emit(Phase::Replay, case);
        Ok(session)
    }
    pub fn effect(&self) -> Effect {
        self.effect.clone()
    }
    pub fn is_done(&self) -> bool {
        matches!(self.effect, Effect::Done { .. })
    }
    fn emit(&mut self, phase: Phase, case: Case) {
        self.effect = Effect::Evaluate {
            id: self.next_id,
            phase,
            case,
        };
        self.next_id += 1;
    }
    fn finish(&mut self, status: TestStatus, reason: Option<String>) {
        self.result.status = status;
        self.result.reason = reason;
        self.result.work = self.work.used;
        self.effect = Effect::Done {
            result: self.result.clone(),
        };
    }
    fn generate(&mut self) {
        let plan = self.plan.as_ref().expect("property plan");
        loop {
            if self.result.cases >= plan.cases {
                self.finish(TestStatus::Passed, None);
                return;
            }
            if self.result.attempts >= plan.max_attempts {
                self.finish(TestStatus::Exhausted, Some("attempts".into()));
                return;
            }
            let index = self.result.attempts;
            self.result.attempts += 1;
            match self.generator.as_ref().expect("generator").generate(
                &mut self.random,
                plan.seed,
                index,
                &mut self.work,
            ) {
                Ok(Some(case)) => {
                    self.emit(Phase::Generation, case);
                    return;
                }
                Ok(None) => self.result.skips += 1,
                Err(()) => {
                    self.finish(TestStatus::Inconclusive, Some("work".into()));
                    return;
                }
            }
        }
    }
    fn shrink_next(&mut self) {
        let shrinker = self.shrinker.as_mut().expect("shrinker");
        let candidate = shrinker.next(self.generator.as_ref().expect("generator"), &mut self.work);
        match candidate {
            Some(case) => self.emit(Phase::Shrink, case),
            None => {
                let case = shrinker.current.clone();
                self.emit(Phase::Confirmation, case);
            }
        }
    }
    pub fn resume(&mut self, id: u32, verdict: Verdict) -> Result<(), Error> {
        let Effect::Evaluate {
            id: expected,
            phase,
            case,
        } = &self.effect
        else {
            return Err(Error::protocol("session has completed"));
        };
        if id != *expected {
            return Err(Error::protocol("feedback id differs from pending request"));
        }
        verdict.validate()?;
        let trial = Trial {
            id,
            phase: *phase,
            case: case.clone(),
            verdict: verdict.clone(),
        };
        let bytes = serde_json::to_vec(&trial)
            .expect("serializable trial")
            .len();
        if self.record_bytes + bytes > 16 * 1024 * 1024 {
            return Err(Error::resource("trial records exceed 16 MiB"));
        }
        self.record_bytes += bytes;
        self.result.trials.push(trial.clone());
        match *phase {
            Phase::Generation | Phase::Baseline => self.baseline(trial, verdict),
            Phase::Shrink => {
                let shrinker = self.shrinker.as_mut().expect("shrinker");
                shrinker.checks += 1;
                match verdict {
                    Verdict::Mismatch { signature } if signature == shrinker.signature => {
                        shrinker.reduced(trial.case)
                    }
                    Verdict::Unknown { .. } => shrinker.unknown = true,
                    Verdict::Error { message } => {
                        self.finish(TestStatus::Error, Some(message));
                        return Ok(());
                    }
                    _ => (),
                }
                self.shrink_next();
            }
            Phase::Confirmation => {
                let shrinker = self.shrinker.as_mut().expect("shrinker");
                shrinker.checks += 1;
                self.result.counterexample = Some(shrinker.current.clone());
                self.result.signature = Some(shrinker.signature.clone());
                self.result.shrink = Some(ShrinkSummary {
                    status: if shrinker.minimal {
                        ShrinkStatus::Minimal
                    } else {
                        ShrinkStatus::Bounded
                    },
                    checks: shrinker.checks,
                });
                let reason = shrinker.reason.clone();
                match verdict {
                    Verdict::Mismatch { signature } if signature == shrinker.signature => {
                        self.finish(TestStatus::Failed, reason)
                    }
                    Verdict::Unknown { reason } => {
                        self.finish(TestStatus::Inconclusive, Some(reason))
                    }
                    Verdict::Error { message } => self.finish(TestStatus::Error, Some(message)),
                    _ => self.finish(TestStatus::Error, Some("not-reproduced".into())),
                }
            }
            Phase::Replay => self.replayed(trial.case, verdict),
        }
        Ok(())
    }
    fn baseline(&mut self, trial: Trial, verdict: Verdict) {
        match verdict {
            Verdict::Matched {} if trial.phase == Phase::Generation => {
                self.result.cases += 1;
                self.generate();
            }
            Verdict::Invalid {} if trial.phase == Phase::Generation => {
                self.result.skips += 1;
                self.generate();
            }
            Verdict::Mismatch { signature } => {
                let maximum = self.plan.as_ref().map_or_else(
                    || self.shrinker.as_ref().expect("shrinker").maximum,
                    |plan| plan.max_shrink_checks,
                );
                self.shrinker = Some(Shrinker::new(trial.case, signature, maximum));
                self.shrink_next();
            }
            Verdict::Unknown { reason } => self.finish(TestStatus::Inconclusive, Some(reason)),
            Verdict::Error { message } => self.finish(TestStatus::Error, Some(message)),
            _ => self.finish(TestStatus::NotFailing, None),
        }
    }
    fn replayed(&mut self, case: Case, verdict: Verdict) {
        if self.replay_signature.is_some()
            && !matches!(&verdict, Verdict::Mismatch { signature } if Some(signature) == self.replay_signature.as_ref())
            && !matches!(verdict, Verdict::Unknown { .. } | Verdict::Error { .. })
        {
            self.finish(TestStatus::Error, Some("not-reproduced".into()));
            return;
        }
        match verdict {
            Verdict::Matched {} => {
                self.result.cases = 1;
                self.finish(TestStatus::Passed, None);
            }
            Verdict::Mismatch { signature } => {
                self.result.counterexample = Some(case);
                self.result.signature = Some(signature);
                self.finish(TestStatus::Failed, None);
            }
            Verdict::Invalid {} => {
                self.result.skips = 1;
                self.finish(TestStatus::Exhausted, Some("invalid".into()));
            }
            Verdict::Unknown { reason } => self.finish(TestStatus::Inconclusive, Some(reason)),
            Verdict::Error { message } => self.finish(TestStatus::Error, Some(message)),
        }
    }
}

use crate::{Case, Generator, Work};
use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct DeletionRange {
    pub start: usize,
    pub count: usize,
}
pub fn deletion_candidates(length: usize) -> Vec<DeletionRange> {
    let mut output = Vec::new();
    let mut seen = BTreeSet::new();
    let mut size = length;
    while size > 0 {
        for start in (0..length).step_by(size) {
            let count = size.min(length - start);
            if seen.insert((start, count)) {
                output.push(DeletionRange { start, count });
            }
        }
        size = if size == 1 { 0 } else { size.div_ceil(2) };
    }
    output
}
pub(crate) struct Shrinker {
    pub current: Case,
    pub signature: String,
    pub checks: u32,
    pub maximum: u32,
    pub minimal: bool,
    pub reason: Option<String>,
    pub unknown: bool,
    ranges: Vec<DeletionRange>,
    cursor: usize,
}
impl Shrinker {
    pub fn new(current: Case, signature: String, maximum: u32) -> Self {
        let ranges = deletion_candidates(current.actions.len());
        Self {
            current,
            signature,
            checks: 1,
            maximum,
            minimal: false,
            reason: None,
            unknown: false,
            ranges,
            cursor: 0,
        }
    }
    pub fn reduced(&mut self, case: Case) {
        self.current = case;
        self.ranges = deletion_candidates(self.current.actions.len());
        self.cursor = 0;
    }
    pub fn next(&mut self, generator: &Generator, work: &mut Work) -> Option<Case> {
        if self.current.actions.is_empty() {
            self.minimal = !self.unknown;
            if self.unknown {
                self.reason = Some("unknown-candidate".into());
            }
            return None;
        }
        if self.checks + 1 >= self.maximum {
            self.reason = Some("checks".into());
            return None;
        }
        while let Some(range) = self.ranges.get(self.cursor) {
            self.cursor += 1;
            let actions = self
                .current
                .actions
                .iter()
                .enumerate()
                .filter(|(index, _)| *index < range.start || *index >= range.start + range.count)
                .map(|(_, value)| value.clone())
                .collect::<Vec<_>>();
            match work.tick().and_then(|()| generator.accepts(&actions, work)) {
                Ok(true) => {
                    return Some(Case {
                        actions,
                        ..self.current.clone()
                    });
                }
                Ok(false) => (),
                Err(()) => {
                    self.reason = Some("work".into());
                    return None;
                }
            }
        }
        self.minimal = !self.unknown;
        if self.unknown {
            self.reason = Some("unknown-candidate".into());
        }
        None
    }
}

use crate::{ActionEdge, Error, Generator, text};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ScheduleActor {
    pub id: String,
    pub operations: Vec<Value>,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Schedule {
    pub id: String,
    pub version: String,
    pub actors: Vec<ScheduleActor>,
}
fn key(positions: &[usize]) -> String {
    positions
        .iter()
        .map(usize::to_string)
        .collect::<Vec<_>>()
        .join(",")
}
impl Schedule {
    pub fn generator(self) -> Result<Generator, Error> {
        text(&self.id)?;
        text(&self.version)?;
        if self.actors.is_empty() {
            return Err(Error::protocol("schedule needs an actor"));
        }
        if self.actors.len() > 8 {
            return Err(Error::resource("schedule exceeds 8 actors"));
        }
        let mut identities = BTreeSet::new();
        let mut state_count = 1_usize;
        let mut operation_count = 0_usize;
        for actor in &self.actors {
            text(&actor.id)?;
            if !identities.insert(&actor.id) {
                return Err(Error::protocol("duplicate schedule actor"));
            }
            operation_count = operation_count
                .checked_add(actor.operations.len())
                .ok_or_else(|| Error::resource("too many schedule operations"))?;
            if operation_count > 128 {
                return Err(Error::resource("schedule exceeds 128 operations"));
            }
            state_count *= actor.operations.len() + 1;
            if state_count > 1024 {
                return Err(Error::resource("schedule exceeds 1024 states"));
            }
        }
        let mut states = BTreeMap::new();
        for index in 0..state_count {
            let mut remaining = index;
            let positions: Vec<_> = self
                .actors
                .iter()
                .map(|actor| {
                    let position = remaining % (actor.operations.len() + 1);
                    remaining /= actor.operations.len() + 1;
                    position
                })
                .collect();
            let edges =
                self.actors
                    .iter()
                    .enumerate()
                    .filter_map(|(index, actor)| {
                        let position = positions[index];
                        actor.operations.get(position).map(|operation| {
                    let mut target = positions.clone(); target[index] += 1;
                    ActionEdge {
                        action: json!({"actor":actor.id,"step":position,"operation":operation}),
                        target: key(&target),
                    }
                })
                    })
                    .collect();
            states.insert(key(&positions), edges);
        }
        Generator {
            id: self.id,
            version: self.version,
            initial: vec![key(&vec![0; self.actors.len()])],
            states,
            min_length: 0,
            max_length: operation_count,
        }
        .normalize()
    }
}

use crate::{Error, canonical, text};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeSet;

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum ComparisonStatus {
    Matched,
    Mismatch,
    Invalid,
    Unknown,
    Error,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Observation {
    Allowed { values: Vec<Value> },
    Value { value: Value },
    Invalid { reason: String },
    Unknown { reason: String },
    Error { message: String },
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Target {
    pub id: String,
    pub outcome: Observation,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Comparison {
    pub id: String,
    pub status: ComparisonStatus,
    pub expected: Vec<Value>,
    pub actual: Option<Value>,
    pub reason: Option<String>,
    pub outcome: Observation,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Differential {
    pub status: ComparisonStatus,
    pub oracle: Observation,
    pub comparisons: Vec<Comparison>,
}
fn unsuccessful(outcome: &Observation) -> Option<(ComparisonStatus, &str)> {
    match outcome {
        Observation::Invalid { reason } => Some((ComparisonStatus::Invalid, reason)),
        Observation::Unknown { reason } => Some((ComparisonStatus::Unknown, reason)),
        Observation::Error { message } => Some((ComparisonStatus::Error, message)),
        _ => None,
    }
}
pub fn compare(oracle: Observation, targets: Vec<Target>) -> Result<Differential, Error> {
    if targets.is_empty()
        || targets.len() > 256
        || targets
            .iter()
            .map(|target| &target.id)
            .collect::<BTreeSet<_>>()
            .len()
            != targets.len()
    {
        return Err(Error::protocol(
            "targets must have nonempty unique identities",
        ));
    }
    let expected = match &oracle {
        Observation::Allowed { values } => {
            if values.len() > 1024 {
                return Err(Error::resource("oracle exceeds 1024 allowed values"));
            }
            values
                .iter()
                .map(|value| canonical(value, 0))
                .collect::<Result<Vec<_>, _>>()?
        }
        Observation::Value { .. } => {
            return Err(Error::protocol("oracle must provide allowed values"));
        }
        _ => vec![],
    };
    if let Some((_, reason)) = unsuccessful(&oracle) {
        text(reason)?;
    }
    let mut comparisons = Vec::new();
    for target in targets {
        text(&target.id)?;
        if matches!(target.outcome, Observation::Allowed { .. }) {
            return Err(Error::protocol("target must provide a single observation"));
        }
        if let Some((_, reason)) = unsuccessful(&target.outcome) {
            text(reason)?;
        }
        let actual = if let Observation::Value { value } = &target.outcome {
            Some(canonical(value, 0)?)
        } else {
            None
        };
        let failure = if matches!(target.outcome, Observation::Error { .. }) {
            unsuccessful(&target.outcome)
        } else {
            unsuccessful(&oracle).or_else(|| unsuccessful(&target.outcome))
        };
        let (status, reason) = if let Some((status, reason)) = failure {
            (status, Some(reason.to_owned()))
        } else if expected.is_empty() {
            (ComparisonStatus::Invalid, Some("empty-oracle".into()))
        } else if actual
            .as_ref()
            .is_some_and(|actual| expected.contains(actual))
        {
            (ComparisonStatus::Matched, None)
        } else {
            (ComparisonStatus::Mismatch, None)
        };
        comparisons.push(Comparison {
            id: target.id,
            status,
            expected: expected.clone(),
            actual,
            reason,
            outcome: target.outcome,
        });
    }
    let status = [
        ComparisonStatus::Error,
        ComparisonStatus::Mismatch,
        ComparisonStatus::Unknown,
        ComparisonStatus::Invalid,
    ]
    .into_iter()
    .find(|status| {
        comparisons
            .iter()
            .any(|comparison| comparison.status == *status)
    })
    .unwrap_or(ComparisonStatus::Matched);
    Ok(Differential {
        status,
        oracle,
        comparisons,
    })
}
